const n35 = node({type:"@n8n/n8n-nodes-langchain.chainLlm",version:1.9,config:{"name":"Extract Text Parameters","parameters":{"promptType":"define","text":expr("{{ JSON.stringify($json.page_prompt) }}"),"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Extract specifications only from the requested current PDF page for target_model. plain_text, layout_text and the attached image, when present, belong to this current page. header_text/header_reference contain only model labels from an earlier header when needed for a continued table; they are auxiliary column-identification context, never a source of parameter rows, values, conditions or footnotes for this page. Do not copy another page's rows or relabel them with the current page number. Earlier reviewed model labels may help a scanned continuation; if the target column or its order still cannot be established from current evidence and the available verified header, omit the uncertain rows rather than guess. Use only this manufacturer's source, not remembered product specifications. Distinguish PV input from battery input, AC from DC protection, operating voltage from startup/full-power MPPT ranges, and target-model cells from neighboring models. Preserve the ORIGINAL source label, value, units, grouping, signs, exact battery/model suffixes and standards. Copy necessary footnote TEXT and conditions, not only its marker. Merged/common cells are allowed only when the source clearly covers target_model. Include all supported rows on this page, including non-numeric features and shared rows. If the page is unrelated, return an empty table and explain. An unclear value is omitted, never guessed.\nA series-cover maximum or 'up to' efficiency/performance headline is not automatically this model's value and is not a constant shared by every family member. Use such a number only when the target-model column or an explicit statement that it is constant across all applicable models supports that scope; otherwise omit the cover claim and leave the value for the technical specification page. Do not derive parameter values from plotted curves, graph labels or digits in model names. Explicitly constant shared parameters and clearly applicable non-numeric features remain eligible; a target-specific maximum in its actual technical column is also valid.\nFor a continuation, source_model_header_sequences preserve the order of labels within actual model-only header lines; confirmed_model_headers records earlier reviewed locators. A single confirmed target label does not certify an entire column order. Do not replace a full source sequence with that one label, combine unrelated sequences, or infer a missing order in a scanned table.\nReturn JSON {applicability:'target'|'shared'|'unrelated'|'uncertain',parameters:[{source_label:string,value:string,unit:string,section:string,conditions:string,footnotes:[string],model:string,scope:'model'|'shared',applies_to_models:[string]}],omissions:[string]}. Model-specific rows may omit applies_to_models. Shared rows must explicitly include target_model. Do not supply IDs, receipts, revisions, hashes, conclusions, translations or analysis. No prose outside JSON."}]},"batching":{"batchSize":1}},"position":[0,1200],"onError":"continueRegularOutput",subnodes:{model:n86}},output:sampleOutput});
const n36 = node({type:"@n8n/n8n-nodes-langchain.chainLlm",version:1.9,config:{"name":"Extract Page Parameters","parameters":{"promptType":"define","text":expr("{{ JSON.stringify($json.page_prompt) }}"),"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Extract specifications only from the requested current PDF page for target_model. plain_text, layout_text and the attached image, when present, belong to this current page. header_text/header_reference contain only model labels from an earlier header when needed for a continued table; they are auxiliary column-identification context, never a source of parameter rows, values, conditions or footnotes for this page. Do not copy another page's rows or relabel them with the current page number. Earlier reviewed model labels may help a scanned continuation; if the target column or its order still cannot be established from current evidence and the available verified header, omit the uncertain rows rather than guess. Use only this manufacturer's source, not remembered product specifications. Distinguish PV input from battery input, AC from DC protection, operating voltage from startup/full-power MPPT ranges, and target-model cells from neighboring models. Preserve the ORIGINAL source label, value, units, grouping, signs, exact battery/model suffixes and standards. Copy necessary footnote TEXT and conditions, not only its marker. Merged/common cells are allowed only when the source clearly covers target_model. Include all supported rows on this page, including non-numeric features and shared rows. If the page is unrelated, return an empty table and explain. An unclear value is omitted, never guessed.\nA series-cover maximum or 'up to' efficiency/performance headline is not automatically this model's value and is not a constant shared by every family member. Use such a number only when the target-model column or an explicit statement that it is constant across all applicable models supports that scope; otherwise omit the cover claim and leave the value for the technical specification page. Do not derive parameter values from plotted curves, graph labels or digits in model names. Explicitly constant shared parameters and clearly applicable non-numeric features remain eligible; a target-specific maximum in its actual technical column is also valid.\nFor a continuation, source_model_header_sequences preserve the order of labels within actual model-only header lines; confirmed_model_headers records earlier reviewed locators. A single confirmed target label does not certify an entire column order. Do not replace a full source sequence with that one label, combine unrelated sequences, or infer a missing order in a scanned table.\nReturn JSON {applicability:'target'|'shared'|'unrelated'|'uncertain',parameters:[{source_label:string,value:string,unit:string,section:string,conditions:string,footnotes:[string],model:string,scope:'model'|'shared',applies_to_models:[string]}],omissions:[string]}. Model-specific rows may omit applies_to_models. Shared rows must explicitly include target_model. Do not supply IDs, receipts, revisions, hashes, conclusions, translations or analysis. No prose outside JSON."},{"type":"HumanMessagePromptTemplate","messageType":"imageBinary","binaryImageDataKey":"page","imageDetail":"high"}]},"batching":{"batchSize":1}},"position":[260,1200],"onError":"continueRegularOutput",subnodes:{model:n87}},output:sampleOutput});
const n37 = node({type:"n8n-nodes-base.code",version:2,config:{"name":"Read Page Draft","parameters":{"mode":"runOnceForAllItems","jsCode":commonCode+"\n\n\nlet state;\ntry{state=clone($('Attach Extraction Images').last().json);}catch{state=clone($('Choose Page').last().json);}\nif(state.current.page!==$('Choose Page').last().json.current.page)state=clone($('Choose Page').last().json);\nconst response=$input.first().json;\ntry{\n const parsed=getOutput(response);if(errText(response))throw new Error(errText(response));\n const source=Array.isArray(parsed.parameters)?parsed.parameters:parsed.rows;\n if(!Array.isArray(source))throw new Error('Page extraction did not return a parameter array');\n if(source.some(row=>row?.page!==undefined&&Number(row.page)!==state.current.page))state.current.omissions.push('Rows explicitly attributed to another page were ignored; only this current page can supply parameter values.');\n state.current.rows=source.map((row,i)=>cleanRow(row,state.current.page,state.current.model,'page'+state.current.page+'-row'+(i+1))).filter(Boolean);\n state.current.extracted=true;state.current.omissions.push(...(Array.isArray(parsed.omissions)?parsed.omissions.map(String):[]));\n state.current.applicability=parsed.applicability||'uncertain';\n state.next_action='audit';\n}catch(error){state.next_action='stop';state.error={stage:'extraction',page:state.current.page,message:error.message};}\ndelete state.page_prompt;return result(state);"},"position":[520,1200],"onError":"continueErrorOutput"},output:sampleOutput});
