const n60 = node({type:"@n8n/n8n-nodes-langchain.chainLlm",version:1.9,config:{"name":"Translate Parameters","parameters":{"promptType":"define","text":expr("{{ JSON.stringify($json) }}"),"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Translate every confidently understood field in this already-reviewed group of product parameters into Chinese. This stage only translates source fields; do not generate product analysis, recommendations, comparisons, positioning or evaluative conclusions. Use only the supplied FINAL source rows, regardless of their language. Retain name_zh and section_zh; add value_zh for values containing descriptive words, conditions_zh for the complete source conditions, and footnotes_zh for every complete source footnote. footnotes_zh must have exactly the same length and order as the row's footnotes: translate each full note separately, without merging, summarizing or dropping its qualifiers. Translate English as well as other languages. For example, Dutch Ja/English Yes in a supported feature can be rendered 支持 or 是 according to the row meaning, Nee/No can be 不支持 or 否, and 0.8 geleidend ... 0.8 na-ijlend means 0.8 超前 ... 0.8 滞后. Preserve the leading/lagging direction and every numeric token exactly. A numeric-only value or a list consisting only of model/standard identifiers does not need value_zh. Never expand a listed standard into a claim of certification.\nThese are display translations alongside the original evidence. Never edit source_label, value, unit, conditions or footnotes. Preserve all numbers and decimal/thousands separators, signs, inequalities, range endpoints, units, battery/model suffixes, standard identifiers, exceptions and operating/test conditions in the translation; do not convert units or infer missing details. Do not add technical specs from memory, reinterpret recommended limits as absolute limits, or treat one operating condition as another. No invented calculations, compatibility or installation advice. If one translated field is uncertain, omit only that optional field and retain other supported translations. For an uncertain footnote translation use an empty string at exactly that position in footnotes_zh and retain all other complete, certain note translations; do not shift positions or partially summarize an uncertain note. Omit footnotes_zh as a whole only if it cannot be aligned to the source note count. A nonempty source footnotes string is a one-note array for this purpose. The original confirmed parameters remain publishable even when translation is unavailable.\nReturn JSON {translations:[{parameter_id:string,name_zh?:string,section_zh?:string,subsection_zh?:string,value_zh?:string,conditions_zh?:string,footnotes_zh?:[string]}]}. Cover every row in this batch; do not shorten the parameter set. Return only translations; do not include sections, paragraphs, overall_limitations_zh or analysis prose. If no fields are understood return {translations:[]}. JSON only."}]},"batching":{"batchSize":1}},"position":[1040,1920],"onError":"continueRegularOutput",subnodes:{model:n86}},output:sampleOutput});
const n61 = node({type:"n8n-nodes-base.code",version:2,config:{"name":"Merge Translations","parameters":{"mode":"runOnceForAllItems","jsCode":commonCode+"\n\n\nconst state=clone($('Build Decision').last().json),translations=[];\ndelete state.decision.analysis;\nfor(const item of $input.all()){\n try{const parsed=getOutput(item.json),extra=Array.isArray(parsed.translations)?parsed:parsed.analysis||parsed;if(errText(item.json)||errText(parsed))throw new Error(errText(item.json)||errText(parsed));\n  translations.push(...cleanTranslations(extra.translations,state.decision.parameters));\n }catch{state.decision.omissions.push('Parameter translation was unavailable for a parameter group.');}\n}\nstate.proposed_translations={translations:cleanTranslations(translations,state.decision.parameters)};return result(state);"},"position":[1300,1920],"onError":"continueErrorOutput"},output:sampleOutput});
const n62 = node({type:"@n8n/n8n-nodes-langchain.chainLlm",version:1.9,config:{"name":"Audit Translations","parameters":{"promptType":"define","text":expr("{{ JSON.stringify({model:$json.decision.model,datasheet_language:$json.decision.official_source?.datasheet_language||\"unknown\",parameters:$json.decision.parameters,translations:$json.proposed_translations.translations}) }}"),"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Independently review EACH proposed Chinese translated field against ONLY its final confirmed source row. This stage only audits translations; do not generate product analysis, recommendations, comparisons, positioning or evaluative conclusions. Check name_zh, section_zh, value_zh, conditions_zh and every footnotes_zh entry for faithful meaning. In value_zh check descriptive/boolean values, polarity and leading/lagging direction. In conditions_zh and footnotes_zh verify complete translation, including all exceptions and applicability limits, not just a summary. footnotes_zh must preserve the exact source footnote count and order. Preserve every source number, numeric separator, sign, inequality, range, unit, model suffix and standard identifier; listed standards do not imply certification. Distinguish startup vs operating vs full-power ranges, recommended vs hard maximum, AC vs DC, and battery compatibility suffixes. Remove claims not supported by those rows and do not introduce new specs. The original source fields must remain unchanged.\nCorrect a mistranslation when its meaning is certain. If one field is uncertain, omit only that field and keep other supported fields. For an uncertain footnote translation keep an empty string at its exact source position, preserving all other complete supported note translations. Omit the entire footnotes_zh array only when its count cannot be aligned; never shift or invent note associations. A nonempty source footnotes string counts as one note. Discard any analysis prose or other content outside the translation fields; preserve valid translations. Do not silently remove translated values/conditions/footnotes while retaining just names. Check every supplied parameter and retain every supported translation without a row-count cap. Missing translations may stay absent rather than guessing; original parameters remain publishable.\nReturn JSON {approved:boolean,translations:[{parameter_id:string,name_zh?:string,section_zh?:string,subsection_zh?:string,value_zh?:string,conditions_zh?:string,footnotes_zh?:[string]}]}. approved:true means the returned translations are supported, not that the proposal was already correct. If no useful supported translations remain, approved:false. Return only the approval flag and translations, without sections, paragraphs, overall_limitations_zh or analysis prose. JSON only."}]},"batching":{"batchSize":1}},"position":[1560,1920],"onError":"continueRegularOutput",subnodes:{model:n86}},output:sampleOutput});
const n63 = node({type:"n8n-nodes-base.code",version:2,config:{"name":"Read Translation Audit","parameters":{"mode":"runOnceForAllItems","jsCode":commonCode+"\n\n\nconst state=clone($('Merge Translations').last().json);\ndelete state.decision.analysis;\ntry{\n const response=$input.first().json;if(response.error)throw new Error(errText(response)||'Translation review returned an error');\n const answer=getOutput(response);if(answer.error)throw new Error(errText(answer)||'Translation review returned an error');\n const translations=cleanTranslations(Array.isArray(answer.translations)?answer.translations:answer.analysis?.translations,state.decision.parameters);\n if(answer.approved===true&&translations.length)state.decision.analysis={translations};\n else state.decision.omissions.push('Parameter translations were omitted after review; confirmed parameters retained.');\n}catch{state.decision.omissions.push('Translation review was unavailable; confirmed parameters retained.');}\ndelete state.proposed_translations;return result(state);"},"position":[0,2160],"onError":"continueErrorOutput"},output:sampleOutput});
